//! Pure fixture comparison. Line endings and trailing blank lines are
//! normalized so a checkout's CRLF policy cannot create a false drift.

use crate::model::Verdict;

fn normalize(text: &str) -> String {
    let unified = text.replace("\r\n", "\n");
    unified.trim_end_matches(['\n', '\r']).to_string()
}

/// Compare a committed fixture against freshly generated bytes.
pub fn compare_fixture(expected: &str, actual: &str) -> Verdict {
    Verdict::from_equal(normalize(expected) == normalize(actual))
}
